<?php require __DIR__.'/oyunchu_config.php';
$allowed=['es_duello_players','tt_scores','zc_scores','mc_scores','sr_scores','sz_results','kz_scores','su_scores','sy_scores'];$game=$_GET['game']??'';$userId=(int)($_GET['user_id']??0);$rows=[];$cols=[];$err='';
if($_SERVER['REQUEST_METHOD']==='POST'){ ga_verify(); if(($_POST['action']??'')==='delete' && in_array($_POST['game']??'', $allowed, true)){ $tg=$_POST['game']; $id=(int)($_POST['id']??0); try{ $q=$conn->prepare("DELETE FROM `$tg` WHERE id=?"); $q->bind_param('i',$id);$q->execute();ga_audit('oyunchu_score_delete',$tg,$id);header('Location: oyunchu_scores.php?game='.urlencode($tg));exit;}catch(Throwable $e){$err='Nəticə silinmədi: '.$e->getMessage();}} }
if($game!==''&&in_array($game,$allowed,true)){try{$where=$userId>0 ? ' WHERE user_id='.(int)$userId : ''; $r=$conn->query("SELECT * FROM `$game`$where ORDER BY id DESC LIMIT 100");$cols=$r->fetch_fields();$rows=$r->fetch_all(MYSQLI_ASSOC);}catch(Throwable $e){$err=$e->getMessage();}}
$games=$conn->query("SELECT slug,default_name,score_table FROM oh_games ORDER BY sort_order,id")->fetch_all(MYSQLI_ASSOC);
?><!doctype html><html lang="az" data-theme="dark"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Nəticələr</title><script>document.documentElement.setAttribute('data-theme',localStorage.getItem('esevgili_theme')||'dark');</script></head><body><?php include __DIR__.'/oyunchu_sidebar.php';?><main class="ga-main"><div class="ga-top"><b>🏆 Oyun nəticələri</b></div><div class="ga-content"><div class="ga-card"><h3>Oyun seç</h3><form method="get" style="margin:12px 0;display:flex;gap:8px;align-items:center;flex-wrap:wrap"><input type="hidden" name="game" value="<?=ga_h($game)?>"><input class="ga-input" style="max-width:220px" type="number" name="user_id" value="<?=$userId?:''?>" placeholder="İstifadəçi ID"><button class="ga-btn ga-mutedbtn">İstifadəçiyə görə filtrlə</button></form><div style="display:flex;gap:8px;flex-wrap:wrap"><?php foreach($games as $g):if(in_array($g['score_table'],$allowed,true)):?><a class="ga-btn <?=$game===$g['score_table']?'ga-primary':'ga-mutedbtn'?>" href="?game=<?=urlencode($g['score_table'])?>"><?=ga_h($g['default_name'])?></a><?php endif;endforeach;?></div></div><br><?php if($err):?><div class="ga-alert err"><?=ga_h($err)?></div><?php elseif($game):?><div class="ga-card"><h3><?=ga_h($game)?> — son 100 nəticə</h3><div style="overflow:auto"><table class="ga-table"><tr><th></th><?php foreach($cols as $c):?><th><?=ga_h($c->name)?></th><?php endforeach;?></tr><?php foreach($rows as $r):?><tr><td><?php if(isset($r['id'])):?><form method="post" onsubmit="return confirm('Bu nəticə silinsin?')"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="game" value="<?=ga_h($game)?>"><input type="hidden" name="id" value="<?=ga_h($r['id'])?>"><button class="ga-btn ga-danger">Sil</button></form><?php endif;?></td><?php foreach($cols as $c):$v=$r[$c->name]??'';if(strlen((string)$v)>100)$v=substr((string)$v,0,100).'…';?><td><?=ga_h($v)?></td><?php endforeach;?></tr><?php endforeach;?></table></div></div><?php else:?><div class="ga-card">Nəticələri görmək üçün oyun seçin.</div><?php endif;?></div></main></body></html>
